mapper.select:
SELECT * FROM sys_notification_delivery

ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE sys_notification_delivery
SET status      = 'SENDING',
    update_time = #{now}
WHERE id = #{id}
  AND status IN ('PENDING', 'FAILED')
  AND (next_retry_time IS NULL OR next_retry_time <= #{now})
